--
-- Table structure for table `reviews`
--

DROP TABLE IF EXISTS `reviews`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `reviews` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `shop_id` int(11) DEFAULT NULL,
  `shop_name` varchar(100) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `source_id` tinyint(3) unsigned NOT NULL,
  `reviewer_nickname` varchar(50) NOT NULL,
  `reviewer_image` varchar(255) DEFAULT NULL,
  `content` text NOT NULL,
  `good_point` varchar(100) DEFAULT NULL,
  `each_visit` varchar(50) DEFAULT NULL,
  `star` tinyint(4) NOT NULL DEFAULT 0,
  `created_at` varchar(50) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_reviews_source` (`source_id`),
  KEY `fk_reviews_shop` (`shop_id`),
  KEY `fk_reviews_user` (`user_id`),
  CONSTRAINT `fk_reviews_shop` FOREIGN KEY (`shop_id`) REFERENCES `shops` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_reviews_source` FOREIGN KEY (`source_id`) REFERENCES `review_sources` (`id`),
  CONSTRAINT `fk_reviews_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=4263 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
