  `shop_loca` varchar(255) DEFAULT NULL,
  `shop_time` varchar(255) DEFAULT NULL,
  `shop_callnum` varchar(255) DEFAULT NULL,
  `shop_sns` varchar(255) DEFAULT NULL,
  `shop_n_rat` float DEFAULT 0,
  `shop_n_rev` int(11) DEFAULT 0,
  `site_avg_star` float DEFAULT 0,
  `site_review_cnt` int(11) DEFAULT 0,
  `solo_good_cnt` int(11) NOT NULL DEFAULT 0,
  `combined_review_cnt` int(11) NOT NULL DEFAULT 0,
  `combined_avg_star` float DEFAULT 0,
  `shop_alon` tinyint(1) DEFAULT 0,
  `shop_extphoto` varchar(255) DEFAULT NULL,
  `shop_intphoto` varchar(255) DEFAULT NULL,
  `shop_menuphoto` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_shops_listnum` (`list_num`)
) ENGINE=InnoDB AUTO_INCREMENT=81 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
